mapper.select:
select

from pro_task

    del_flag = '0'
    and workorder_id = #{workorderId}

        and workorder_code like concat('%', #{workorderCode}, '%')


        and task_code like concat('%', #{taskCode}, '%')

    and process_id = #{processId}
    and workstation_id = #{workstationId}
    and status = #{status}
    and start_time >= #{startTime}
    and start_time <= #{endTime}

order by start_time asc, task_code asc

mapper.update:
update pro_task
task_name = #{taskName}, workstation_id = #{workstationId}, workstation_code = #{workstationCode}, workstation_name = #{workstationName}, quantity = #{quantity}, start_time = #{startTime}, duration = #{duration}, end_time = #{endTime}, color_code = #{colorCode}, status = #{status}, finish_date = #{finishDate}, cancel_date = #{cancelDate}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime},
where task_id = #{taskId}

update pro_task
quantity_produced = ifnull(quantity_produced, 0) + #{produced}, quantity_qualified = ifnull(quantity_qualified, 0) + #{qualified}, quantity_unqualified = ifnull(quantity_unqualified, 0) + #{unqualified}, status = #{status}, finish_date = #{finishDate}, update_by = #{updateBy}, update_time = #{updateTime},
where task_id = #{taskId}
